(()=>{'use strict';
const D=window.ABDI_DATA,T=window.ABDI_TOPICS;
const SUBJECTS=D.subjects,KEY='rumo-abdi-v1',GOAL=3000,EXAM='2026-12-20',SUBGOALS={prod:1200,inst:900,port:360,logic:270,info:270};
const nav=[['home','⌂','Início'],['practice','✎','Resolver'],['plan','◎','Meta 3.000'],['gaps','▤','Lacunas'],['bank','▣','Banco']];
const LINKS=[
 {name:'FGV · EBSERH 2025 · Engenheiro de Produção (caderno Tipo 1)',org:'FGV',focus:'60 questões aplicadas; português, engenharia de produção e gestão. Selecione apenas temas do edital ABDI.',url:'https://conhecimento.fgv.br/sites/default/files/concursos/grupo-8-engenheiro-de-producaoe4cnsgp08-tipo-1.pdf'},
 {name:'FGV · EBSERH 2025 · Gabarito definitivo',org:'FGV',focus:'Gabarito definitivo do caderno de Engenheiro de Produção, Tipo 1.',url:'https://conhecimento.fgv.br/sites/default/files/concursos/ebserhadministrativo2024_gabarito_definitivo.pdf'},
 {name:'FGV · AMAZUL 2025 · Engenheiro de Produção (caderno)',org:'FGV',focus:'Questões de engenharia, qualidade, projetos e produção.',url:'https://conhecimento.fgv.br/sites/default/files/concursos/ok-engenheiro-producao-cnse221-tipo-1-2.pdf'},
 {name:'FGV · MPES 2026 · Engenheiro de Produção',org:'FGV',focus:'Prova e gabaritos oficiais; selecione o cargo de Engenharia de Produção.',url:'https://conhecimento.fgv.br/concursos/mpes26'},
 {name:'FGV · EPE 2024 · Analista de Gestão Corporativa',org:'FGV',focus:'Gestão, projetos, português, informática e organização.',url:'https://conhecimento.fgv.br/concursos/epe24/2'},
 {name:'FGV · EPE 2024 · Analista de Pesquisa Energética',org:'FGV',focus:'Sustentabilidade, investimento e programas de energia.',url:'https://conhecimento.fgv.br/concursos/epe24/3'},
 {name:'FGV · COMPESA 2016 · Engenheiro de Produção (caderno)',org:'FGV',focus:'Processos, métodos, gestão e conhecimentos gerais.',url:'https://conhecimento.fgv.br/sites/default/files/concursos/compesa2016/201605_Analista_de_Saneamento_%28Engenheiro_de_Producao%29_%28NS003%29_Tipo_1.pdf'},
 {name:'FGV · CVM 2024 · Analista',org:'FGV',focus:'Português, raciocínio, informática e análise institucional.',url:'https://conhecimento.fgv.br/concursos/cvm24'},
 {name:'CEBRASPE · ANTT 2023/24 · Especialista (Engenharia)',org:'CEBRASPE',focus:'Outra banca: projetos, engenharia e análise. Atenção ao formato certo/errado.',url:'https://www.cebraspe.org.br/concursos/antt_23'},
 {name:'FGV · Portal do processo seletivo ABDI 2026',org:'FGV',focus:'Edital atualizado e comunicados oficiais.',url:'https://conhecimento.fgv.br/concursos/psabdi'},
 {name:'ABDI · Legislação e regulamentos',org:'ABDI',focus:'Conhecimentos institucionais específicos — questões antigas de outras organizações não substituem esta leitura.',url:'https://www.abdi.com.br/legislacao-aplicavel/'}
];
let base={history:[],lessons:[],notes:{},sessions:[],errorReasons:{}};
try{base={...base,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(e){}
if(!Array.isArray(base.history))base.history=[];if(!Array.isArray(base.sessions))base.sessions=[];if(!base.errorReasons)base.errorReasons={};
let imported=[],db=null,dbFailure=false,page='home',session=null,practiceFilter={subject:'all',topic:'all',kind:'all',count:15,mode:'practice'},bankFilter='all',topicFilter='all',gapFilter='unseen',moreLinks=false;
let noteTopic=null,lastFocus=null;
const $=s=>document.querySelector(s),H=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>/^https?:\/\//i.test(String(u||''))?H(u):'#';
const letters=q=>q.options?.length===2?['C','E']:['A','B','C','D','E'];
const S=id=>SUBJECTS.find(x=>x.id===id), Tp=id=>T.find(x=>x.id===id), all=()=>[...seeded,...imported];
const dayString=dt=>{const d=new Date(dt);return isNaN(+d)?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const today=()=>dayString(new Date()),daysRemain=()=>Math.max(0,Math.ceil((new Date(2026,11,20)-new Date(new Date().getFullYear(),new Date().getMonth(),new Date().getDate()))/86400000));
const dateDisplay=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR');
const percent=(a,b)=>b?Math.round(100*a/b):0;
const inDate=(iso,days)=>{const d=new Date();d.setDate(d.getDate()-days);return new Date(iso)>=d};
const legacyMap={
 'port|Interpretação e coesão':'port_01','port|Gramática e reescrita':'port_18',
 'logic|Proposições e inferências':'logic_04','logic|Problemas quantitativos':'logic_09',
 'info|Ferramentas e sistemas':'info_05','info|Segurança e dados':'info_11',
 'inst|Serviços sociais autônomos':'inst_01','inst|Criação e estatuto':'inst_08','inst|Licitações e convênios':'inst_12','inst|Ética e estratégia':'inst_22',
 'prod|Produtividade e indicadores':'prod_02','prod|Lean, PCP e estoques':'prod_08','prod|Qualidade e OEE':'prod_13','prod|Indústria 4.0':'prod_15','prod|Inovação e viabilidade':'prod_24','prod|Sustentabilidade':'prod_25','prod|ABDI, NIB e programas':'prod_30'
};
function normalizeSeed(q){return {...q,topicId:legacyMap[q.subject+'|'+q.topic]||T.find(t=>t.subject===q.subject)?.id,kind:'autoral',board:'Autoral',exam:'Treino original',year:2026,questionNo:null,sourceUrl:''}}
const seeded=D.questions.map(normalizeSeed),qIndex=new Map(seeded.map(q=>[q.id,q]));
const reindex=()=>{qIndex.clear();for(const q of seeded)qIndex.set(q.id,q);for(const q of imported)qIndex.set(q.id,q)};
function save(){try{localStorage.setItem(KEY,JSON.stringify(base))}catch(e){alert('Sem espaço para salvar o progresso. Exporte o backup na aba Banco.') }}
function openDb(){return new Promise((resolve)=>{if(typeof indexedDB==='undefined'){dbFailure=true;resolve(null);return}let req;try{req=indexedDB.open('RumoABDI_questoes_v2',1)}catch(e){dbFailure=true;resolve(null);return}req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains('questions'))d.createObjectStore('questions',{keyPath:'id'})};req.onsuccess=()=>{db=req.result;resolve(db)};req.onerror=()=>{dbFailure=true;resolve(null)}})}
function loadDb(){return new Promise(resolve=>{if(!db){resolve([]);return}const tx=db.transaction('questions','readonly'),r=tx.objectStore('questions').getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>resolve([])})}
function addDb(questions){return new Promise((resolve,reject)=>{if(!db){reject(Error('O navegador bloqueou IndexedDB. Publique em HTTPS e abra no Safari.'));return}const tx=db.transaction('questions','readwrite');const st=tx.objectStore('questions');questions.forEach(q=>st.put(q));tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||Error('Erro no banco local'))})}
function clearDb(){return new Promise(resolve=>{if(!db){resolve();return}const tx=db.transaction('questions','readwrite');tx.objectStore('questions').clear();tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()})}
const uniqueItems=(kind=null)=>{const ids=new Set();for(const h of base.history){const q=findQuestion(h.id);if(q&&(!kind||q.kind===kind))ids.add(h.id)}return ids.size};
const validHistory=()=>base.history.filter(h=>!!findQuestion(h.id));
const hist=()=>validHistory().filter(h=>findQuestion(h.id)?.kind==='aplicada');
const firstAnswers=()=>{const seen=new Set(),items=[];for(const h of validHistory()){if(!seen.has(h.id)){seen.add(h.id);items.push(h)}}return items};

const uniqueBySubject=()=>{const ids={};for(const s of SUBJECTS)ids[s.id]=new Set();for(const h of validHistory()){const q=findQuestion(h.id);if(q&&ids[q.subject])ids[q.subject].add(q.id)}return Object.fromEntries(Object.entries(ids).map(([k,v])=>[k,v.size]))};
const fortnight=()=>{const recent=validHistory().filter(h=>inDate(h.date,14));const half=7*86400000;const now=Date.now();const groups=[recent.filter(h=>now-new Date(h.date).getTime()<half),recent.filter(h=>now-new Date(h.date).getTime()>=half)];return groups.map(g=>({n:g.length,ok:g.filter(h=>h.correct).length,pct:percent(g.filter(h=>h.correct).length,g.length)}))};

const perTopic=()=>{const out={};for(const t of T)out[t.id]={...t,total:0,correct:0,unique:new Set(),recent:[],miss:{}};
for(const h of base.history){const q=findQuestion(h.id),id=h.topicId||q?.topicId;if(!out[id])continue;const x=out[id];x.total++;x.correct+=Number(!!h.correct);x.unique.add(h.id);x.recent.push(h);if(!h.correct){const reason=base.errorReasons[h.id]||'A classificar';x.miss[reason]=(x.miss[reason]||0)+1;}}
for(const x of Object.values(out)){x.distinct=x.unique.size;delete x.unique;x.pct=percent(x.correct,x.total);x.recent=x.recent.slice(-12);x.trend=x.recent.length>=6?percent(x.recent.filter(h=>h.correct).length,x.recent.length):null;
x.status=x.total===0?'Não iniciado':x.distinct<5?'Amostra pequena':x.pct<75?'Revisar':'Em evolução';}return out};
const totals=()=>{const p=perTopic(),legacy=uniqueItems('autoral'),real=uniqueItems('aplicada'),history=validHistory(),first=firstAnswers(),correct=history.filter(h=>h.correct).length;return {p,legacy,real,answered:history.length,all:first.length,daily:first.filter(h=>dayString(h.date)===today()).length,correct,wrong:history.length-correct,covered:Object.values(p).filter(x=>x.total>0).length,weak:Object.values(p).filter(x=>x.status==='Revisar').length}};
function findQuestion(id){return qIndex.get(id)}
function nameSubject(id){return S(id)?.name||id}
function dLabel(q){return q.kind==='aplicada'?`${H(q.board)} · ${H(q.year)} · ${H(q.exam)} · Q${H(q.questionNo)}`:'Autoral · treino de fixação'}
function layout(body){const head=`<header class="topbar"><div class="brand" data-page="home"><div class="brand-mark">R</div><div><div class="brand-title">Rumo à ABDI</div><div class="brand-sub">Missão 3.000 · Produtividade Industrial</div></div></div><div class="toplinks">${nav.map(([id,x,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${label}</button>`).join('')}</div></header>`;
const foot=`<nav class="bottomnav">${nav.map(([id,ico,label])=>`<button class="${page===id?'active':''}" data-page="${id}"><span>${ico}</span>${label}</button>`).join('')}</nav>`;
$('#app').innerHTML=`<main class="app-shell">${head}${body}<footer class="footer">Aplicativo independente, sem afiliação com FGV/ABDI. 166 questões iniciais autorais. Provas anteriores: fontes oficiais linkadas. Questões importadas têm origem informada pelo importador; não há verificação automática da autenticidade. Dados salvos apenas neste dispositivo. O conteúdo deve ser conferido no edital e nos regulamentos vigentes.</footer></main>${foot}`}
function bar(n,d,cls=''){return `<div class="meter ${cls}"><span style="width:${Math.min(100,percent(n,d))}%"></span></div>`}
const sc=x=>`<div class="card kpi"><div class="stat-label">${x.label}</div><div class="stat-value">${x.value}</div><div class="stat-help">${x.help||''}</div></div>`;

function performanceDashboard(){
 const history=validHistory(),good=history.filter(h=>h.correct).length,bad=history.length-good,rate=history.length?Math.round(good*100/history.length):0;
 const split=filter=>{const a=history.filter(filter);return {n:a.length,good:a.filter(h=>h.correct).length,bad:a.filter(h=>!h.correct).length,unique:new Set(a.map(h=>h.id)).size}};
 const groups=[{name:'Autorais da IA',kind:'autoral'},{name:'Provas anteriores',kind:'aplicada'}];
 return `<div class="section-title"><h2>Gráfico de acertos e erros</h2></div>
 <div class="card">
 <p class="listnote">O gráfico considera todas as tentativas respondidas; as revisões entram no desempenho, mas não aumentam a contagem de 3.000 questões diferentes.</p>
 <div class="pie-wrap">
 <div class="score-pie" role="img" aria-label="${good} acertos, ${bad} erros" style="background:${history.length?`conic-gradient(var(--mint) 0 ${rate}%,var(--red) ${rate}% 100%)`:'var(--line)'}"></div>
 <div class="pie-details"><div class="stat-label">Seu aproveitamento</div><div class="stat-value">${history.length?rate+'%':'—'}</div><div class="pie-legend"><span class="pie-swatch correct"></span> Acertos <strong>${good}</strong></div><div class="pie-legend"><span class="pie-swatch incorrect"></span> Erros <strong>${bad}</strong></div><div class="listnote">${history.length} tentativas registradas</div></div></div></div>
 <div class="section-title"><h2>Por origem das questões</h2></div>
 <div class="card">${groups.map(g=>{const v=split(h=>findQuestion(h.id)?.kind===g.kind);return `<div class="study-breakdown"><div class="row between"><strong>${g.name}</strong><span>${v.n?Math.round(v.good/v.n*100)+'%':'Sem respostas'}</span></div><p class="listnote">${v.unique} distintas · ${v.good} acertos · ${v.bad} erros · ${v.n} tentativas</p>${bar(v.good,v.n)}</div>`}).join('')}</div>
 <div class="section-title"><h2>Por disciplina</h2></div>
 <div class="card">${SUBJECTS.map(d=>{const v=split(h=>findQuestion(h.id)?.subject===d.id);return `<div class="study-breakdown"><div class="row between"><strong>${H(d.name)}</strong><span>${v.n?Math.round(v.good/v.n*100)+'%':'Sem respostas'}</span></div><p class="listnote">${v.unique} distintas · ${v.good} acertos · ${v.bad} erros</p>${bar(v.good,v.n)}</div>`}).join('')}</div>`;
}
function home(){const k=totals(),need=Math.max(0,GOAL-k.all),dailyGoal=daysRemain()?Math.ceil(need/daysRemain()):need,remain=daysRemain();const ranked=Object.values(k.p).filter(t=>t.total>0&&t.pct<75).sort((a,b)=>a.pct-b.pct).slice(0,3);
return `<div class="hero"><div class="eyebrow">Plano de questões · ABDI 2026</div><h1>3.000 questões.<br><span style="color:var(--mint)">Lacunas visíveis, revisões certas.</span></h1><p>Estude por questões, acompanhe sua curva de acertos e veja os temas não cobertos, com amostra insuficiente ou que precisam de reforço.</p><div class="pills"><span class="pill">${remain} dias até a prova</span><span class="pill">${T.length} tópicos mapeados</span><span class="pill amber">20 dez · 13h30</span></div><div class="buttons"><button class="btn primary" data-page="practice">Resolver questões →</button><button class="btn" data-page="bank">Adicionar provas antigas</button></div></div>
<div class="grid three" style="margin-top:16px">${sc({label:'Questões distintas concluídas',value:`${k.all} / ${GOAL}`,help:'Autorais + provas anteriores; sem repetições'})}${sc({label:'Meta diária restante',value:`${dailyGoal}`,help:`${remain} dias de treino até 19/12`})}${sc({label:'Cobertura do programa',value:`${k.covered}/${T.length}`,help:'Tópicos com ao menos uma resposta'})}</div>
<div class="card" style="margin-top:15px"><div class="row between"><strong>Progresso rumo às 3.000 questões</strong><b>${percent(k.all,GOAL)}%</b></div>${bar(k.all,GOAL)}<p class="listnote">Hoje: ${k.daily} questões novas concluídas. Total: ${k.legacy} autorais + ${k.real} históricas. Resolver uma questão novamente conta como revisão.</p></div>${performanceDashboard()}
<div class="section-title"><h2>Próximo treino recomendado</h2><button class="btn small" data-page="gaps">Diagnosticar lacunas →</button></div>
${ranked.length?ranked.map(t=>`<div class="card gap-preview"><div class="row between"><strong>${H(t.name)}</strong><span class="tag amber">${t.pct}% · ${t.total} tentativas</span></div><p class="listnote">${H(t.tip)}</p><button class="btn small" data-action="train-topic" data-topic="${t.id}">Reforçar este tema →</button></div>`).join(''):`<div class="card"><p>Você ainda não tem amostra suficiente para detectar erros recorrentes. Comece resolvendo questões, preferencialmente de provas aplicadas.</p><button class="btn small" data-page="practice">Fazer diagnóstico inicial</button></div>`}
<div class="section-title"><h2>As fontes históricas</h2><button class="btn small" data-page="bank">Ver todas →</button></div><div class="card"><p class="listnote">Provas oficiais da FGV de Engenharia de Produção, gestão, pesquisa energética e disciplinas comuns. Os PDFs e gabaritos ficam nos sites da organizadora, não são reproduzidos integralmente neste app.</p>${LINKS.slice(0,3).map(x=>`<div class="resource-link"><div><a href="${safeUrl(x.url)}" target="_blank" rel="noopener">${H(x.name)} ↗</a><p>${H(x.focus)}</p></div></div>`).join('')}</div>`}
function plan(){const k=totals(),rem=daysRemain(),need=Math.max(0,GOAL-k.all),daily=rem?Math.ceil(need/rem):need;const byDay={};for(const h of firstAnswers()){const d=dayString(h.date);(byDay[d]??=new Set()).add(h.id)}const days=Object.entries(byDay).sort().slice(-14);
return `<div class="page-header"><div class="eyebrow">Contagem regressiva</div><h1>Missão 3.000 questões</h1><p>Meta combinada: questões autorais da IA e questões de provas anteriores. Cada questão diferente conta uma vez; revisões são acompanhadas separadamente.</p></div>
<div class="grid three">${sc({label:'Questões distintas',value:k.all,help:`${k.legacy} autorais + ${k.real} históricas`})}${sc({label:'Restantes',value:need,help:'Até alcançar a meta'})}${sc({label:'Ritmo necessário',value:`${daily}/dia`,help:`${rem} dias antes da prova`})}</div>${performanceDashboard()}
<div class="card" style="margin-top:15px"><strong>Distribuição diária sugerida para o programa</strong><p class="listnote">Prioriza a parte específica, que vale mais pontos na prova, sem abandonar as 40 questões de conhecimentos gerais e institucionais.</p>${[['Produtividade Industrial',25],['Conhecimentos Institucionais',19],['Português',8],['Raciocínio Lógico',6],['Informática',5]].map(([x,n])=>`<div class="row between target-row"><span>${x}</span><strong>${n}</strong></div>`).join('')}<p class="listnote">Se houver atraso, o ritmo restante sobe automaticamente; com antecipação, diminui.</p></div>
<div class="section-title"><h2>Meta por matéria</h2></div><div class="card">${SUBJECTS.map(x=>{const done=uniqueBySubject()[x.id]||0,goal=SUBGOALS[x.id];return `<div class="topic-target"><div class="row between"><span>${H(x.name)}</span><strong>${done}/${goal}</strong></div>${bar(done,goal)}</div>`}).join('')}<p class="listnote">As cotas foram propostas para cobrir o programa e dar atenção extra aos conhecimentos específicos. Elas não representam previsão da distribuição de questões da prova.</p></div>
<div class="section-title"><h2>Evolução das últimas duas semanas</h2></div><div class="card">${(()=>{const e=fortnight(),cur=e[0],prior=e[1];return `<div class="row between"><span>Últimos 7 dias</span><strong>${cur.n?cur.pct+'%':'Sem dados'}</strong></div>${bar(cur.ok,cur.n)}<div class="row between" style="margin-top:15px"><span>7 dias anteriores</span><strong>${prior.n?prior.pct+'%':'Sem dados'}</strong></div>${bar(prior.ok,prior.n)}<p class="listnote">${cur.n>=10&&prior.n>=10?`Variação: ${cur.pct-prior.pct>=0?'+':''}${cur.pct-prior.pct} pontos percentuais. Compare também o nível de dificuldade das questões.`:'É necessário resolver pelo menos 10 questões em cada período para comparar as duas janelas com alguma utilidade.'}</p>`})()}</div>
<div class="section-title"><h2>Últimos dias registrados</h2></div><div class="card">${days.length?days.map(([d,ids])=>`<div class="row between target-row"><span>${dateDisplay(d)}</span><strong>${ids.size} questões distintas</strong></div>`).join(''):'<p class="listnote">Ainda não há questões concluídas. Comece pelas autorais ou importe resultados de provas antigas.</p>'}</div>
<div class="section-title"><h2>Como interpretar a meta</h2></div><div class="card"><p class="listnote"><strong>Uma questão distinta = um ID de questão, seja ela autoral ou histórica.</strong> Resolver a mesma questão três vezes significa três tentativas, mas apenas uma questão concluída na meta. Acompanhamos separadamente erros, revisões, desempenho e cobertura por tópico.</p><p class="listnote">As ${D.questions.length} questões iniciais autorais contam para a meta quando você as responde. Elas permanecem identificadas como autorais, nunca como questões históricas.</p><button class="btn small" data-page="bank">Importar acervo histórico →</button></div>`}
function gaps(){const k=totals(),ps=Object.values(k.p),available=all();let filtered=[...ps];if(gapFilter==='weak')filtered=ps.filter(t=>t.status==='Revisar');if(gapFilter==='unseen')filtered=ps.filter(t=>t.status==='Não iniciado');if(gapFilter==='sample')filtered=ps.filter(t=>t.status==='Amostra pequena');filtered.sort((a,b)=>{const weights={prod:0,inst:1,port:2,logic:3,info:4};return (weights[a.subject]-weights[b.subject])||(a.pct-b.pct)||a.name.localeCompare(b.name)});const counted=ps.map(t=>t.status);let noCover=counted.filter(x=>x==='Não iniciado').length;let small=counted.filter(x=>x==='Amostra pequena').length;
return `<div class="page-header"><div class="eyebrow">Mapa de domínio do edital</div><h1>Seus pontos cegos</h1><p>O app mostra não apenas erros, mas também conteúdo que você ainda não testou, conhecimento com pouca amostra e temas abaixo da meta de 75% de acerto.</p></div>
<div class="grid three">${sc({label:'Sem tentativa',value:noCover,help:'Tópicos ainda não cobridos'})}${sc({label:'Amostra pequena',value:small,help:'Menos de 5 questões distintas'})}${sc({label:'Abaixo de 75%',value:k.weak,help:'Lacunas observadas nos acertos'})}</div>
<div class="field"><label for="gap-status">Filtrar diagnóstico</label><select id="gap-status"><option value="weak" ${gapFilter==='weak'?'selected':''}>Abaixo da meta (menos de 75%)</option><option value="unseen" ${gapFilter==='unseen'?'selected':''}>Nunca estudados</option><option value="sample" ${gapFilter==='sample'?'selected':''}>Pouca amostra</option><option value="all" ${gapFilter==='all'?'selected':''}>Todo o edital (${T.length} tópicos)</option></select></div>
${filtered.length?filtered.map(t=>{const pool=available.filter(q=>q.topicId===t.id).length;const mistakes=Object.entries(t.miss).sort((a,b)=>b[1]-a[1]);return `<div class="card gap-row"><div class="row between"><div class="tiny">${H(nameSubject(t.subject))}</div><span class="tag ${t.status==='Revisar'?'amber':t.status==='Em evolução'?'green':''}">${H(t.status)}</span></div><strong>${H(t.name)}</strong><div class="row between"><span class="tiny">${t.correct}/${t.total} acertos (${t.pct}%) · ${t.distinct} distintas</span><span class="tiny">${pool} no banco</span></div>${bar(t.correct,t.total)}${t.total?`<p class="listnote">${t.trend!==null?'Últimas tentativas: '+t.trend+'% de acertos. ':''}${mistakes.length?'Erros marcados: '+mistakes.map(([r,n])=>`${H(r)} (${n})`).join(', ')+'.':''}</p>`:''}<p class="tip">💡 ${H(t.tip)}</p><div class="buttons"><button class="btn small" data-action="train-topic" data-topic="${t.id}" ${pool?'':'disabled'}>Treinar assunto</button><button class="btn small" data-action="note-topic" data-topic="${t.id}">Minha anotação</button></div>${base.notes[t.id]?`<p class="listnote">📝 ${H(base.notes[t.id])}</p>`:''}</div>`}).join(''):'<div class="empty">Nenhum assunto nessa categoria. Continue os treinos e acompanhe a evolução.</div>'}
${noteTopic&&Tp(noteTopic)?`<div class="card"><strong>Anotação: ${H(Tp(noteTopic).name)}</strong><div class="field"><textarea id="topic-note" placeholder="O que eu confundi? Qual regra preciso memorizar?">${H(base.notes[noteTopic]||'')}</textarea></div><button class="btn primary" data-action="save-topic-note" data-topic="${noteTopic}">Salvar explicação</button></div>`:''}`}
function practice(){const k=totals(),subs=SUBJECTS.map(s=>`<option value="${s.id}" ${practiceFilter.subject===s.id?'selected':''}>${H(s.name)}</option>`).join('');const subjects=practiceFilter.subject==='all'?T:T.filter(t=>t.subject===practiceFilter.subject);
const possible=all().filter(q=>(practiceFilter.subject==='all'||q.subject===practiceFilter.subject)&&(practiceFilter.topic==='all'||q.topicId===practiceFilter.topic)&&(practiceFilter.kind==='all'||q.kind===practiceFilter.kind));
return `<div class="page-header"><div class="eyebrow">Estudo por questões</div><h1>Resolver e aprender</h1><p>Correção imediatamente após responder, justificativa, marcação da causa do erro e revisão direcionada. No simulado, as explicações aparecem no final.</p></div>
<div class="card"><div class="field"><label>Matéria</label><select id="p-sub"><option value="all">Todas as disciplinas</option>${subs}</select></div><div class="field"><label>Assunto do edital</label><select id="p-topic"><option value="all">Todos os tópicos</option>${subjects.map(t=>`<option value="${t.id}" ${practiceFilter.topic===t.id?'selected':''}>${H(t.name)}</option>`).join('')}</select></div><div class="field"><label>Origem do banco</label><select id="p-kind"><option value="all" ${practiceFilter.kind==='all'?'selected':''}>Todas · históricas + autorais</option><option value="aplicada" ${practiceFilter.kind==='aplicada'?'selected':''}>Somente provas anteriores (importadas)</option><option value="autoral" ${practiceFilter.kind==='autoral'?'selected':''}>Somente autorais (166 iniciais)</option></select></div><div class="field"><label>Quantidade de questões</label><select id="p-count">${[10,15,20,30,60,100].map(n=>`<option value="${n}" ${practiceFilter.count===n?'selected':''}>${n} questões</option>`).join('')}</select></div><div class="row between"><span class="tag">${possible.length} questões neste filtro</span><span class="tiny">Prioriza questões inéditas para você</span></div><div class="buttons"><button class="btn primary" data-action="start-filter">Iniciar treino →</button><button class="btn" data-action="start-mock">Simulado ABDI · 60</button><button class="btn" data-action="start-errors">Revisar erros</button></div></div>
<div class="card" style="margin-top:14px"><strong>Como identificamos lacunas?</strong><p class="listnote">Cada resposta é associada a um dos ${T.length} tópicos detalhados do edital. Ao errar, marque se a causa foi conceito, interpretação, cálculo ou desatenção. O relatório cruza desempenho, temas ignorados e frequência de erros.</p></div>`}
function bank(){const k=totals(),applied=imported.filter(q=>q.kind==='aplicada');const groups={};for(const q of applied){const key=`${q.board} · ${q.year} · ${q.exam}`;groups[key]=(groups[key]||0)+1}let byBoard={};for(const q of applied)byBoard[q.board]=(byBoard[q.board]||0)+1;
return `<div class="page-header"><div class="eyebrow">Acervo verificável e importações</div><h1>Banco de questões</h1><p>Nenhuma das 3.000 questões históricas foi incorporada automaticamente. Importe materiais com autorização de uso e referências completas. As questões autorais já instaladas continuam acessíveis.</p></div>
<div class="grid three">${sc({label:'Históricas importadas',value:applied.length,help:'Origem declarada com prova e questão'})}${sc({label:'Autorais incluídas',value:D.questions.length,help:'Não contam para a meta 3.000'})}${sc({label:'Provas no seu banco',value:Object.keys(groups).length,help:'Identificadas por banca, ano e prova'})}</div>
<div class="card" style="margin-top:15px"><h2 style="margin-top:0">Importar questões de fontes permitidas</h2><p class="listnote">Aceita CSV ou JSON com enunciado, alternativas A–E, gabarito, matéria, tópico, banca, ano, prova, número da questão, URL da fonte e comentário. Os arquivos são processados somente no aparelho e salvos em IndexedDB.</p>
<div class="buttons"><button class="btn primary" data-action="import-questions">Escolher CSV ou JSON</button><button class="btn" data-action="download-model">Baixar modelo CSV</button><button class="btn" data-action="download-topics">Lista de tópicos e códigos</button></div><input class="hide" type="file" id="questions-file" accept=".csv,.json,text/csv,application/json" multiple><p class="listnote" style="margin-top:12px">${dbFailure?'⚠ Seu navegador bloqueou o banco local; abra a versão hospedada em HTTPS no Safari.':'O acervo permanece disponível no aparelho após fechar o aplicativo; faça backup regularmente.'} Itens sem metadados mínimos de prova são registrados como autorais/não verificados, nunca como históricos.</p></div>
<div class="card" style="margin-top:15px"><h2 style="margin-top:0">Registrar resultados de cadernos em lote</h2><p class="listnote">Resolveu 30, 60 ou mais questões em PDFs oficiais ou em plataforma licenciada? Importe um CSV com uma linha por questão: banca, ano, prova, número, matéria, tópico do edital, resultado e URL de origem. O sistema contabiliza cada questão distinta uma única vez na meta e preserva tentativas repetidas para análise de aprendizagem.</p><div class="buttons"><button class="btn primary" data-action="import-results">Importar resultados CSV</button><button class="btn" data-action="download-results-model">Baixar modelo do registro</button></div><input class="hide" type="file" id="results-file" accept=".csv,text/csv" multiple><p class="listnote">É você quem declara a origem e o acerto. O app não verifica a autenticidade da questão ou a correspondência do número com o gabarito. Selecione apenas questões relacionadas ao edital.</p></div>
<div class="card" style="margin-top:15px"><h2 style="margin-top:0">Registro manual de questão histórica</h2><p class="listnote">Útil quando você está resolvendo um caderno PDF oficial. Adicione a referência de cada questão resolvida para acompanhar os 3.000 itens e sua lacuna. A explicação será aquela registrada por você; o aplicativo não inventa um comentário oficial.</p>
<div class="grid two"><div class="field"><label>Banca</label><input id="m-board" placeholder="FGV"></div><div class="field"><label>Ano</label><input id="m-year" type="number" inputmode="numeric" placeholder="2024"></div></div>
<div class="field"><label>Nome da prova/cargo</label><input id="m-exam" placeholder="EBSERH · Engenheiro de Produção"></div>
<div class="grid two"><div class="field"><label>Número da questão</label><input id="m-number" type="number" inputmode="numeric" placeholder="17"></div><div class="field"><label>Resultado</label><select id="m-result"><option value="ok">Acertei</option><option value="wrong">Errei</option></select></div></div>
<div class="field"><label>Matéria</label><select id="m-sub"><option value="">Escolha</option>${SUBJECTS.map(s=>`<option value="${s.id}">${H(s.name)}</option>`).join('')}</select></div><div class="field"><label>Tópico do edital</label><select id="m-topic"><option value="">Escolha a matéria acima</option></select></div>
<div class="field"><label>URL pública do caderno ou prova (obrigatória)</label><input type="url" id="m-url" placeholder="https://conhecimento.fgv.br/..."></div>
<div class="field"><label>Aprendizado ou explicação (opcional)</label><textarea id="m-comment" placeholder="Regra que eu errei, solução e onde revisar…"></textarea></div>
<button class="btn small" data-action="manual-register">Registrar questão concluída</button></div>
<div class="section-title"><h2>Fontes oficiais de provas anteriores</h2></div><div class="card">${LINKS.map(l=>`<div class="resource-link"><div><a href="${safeUrl(l.url)}" target="_blank" rel="noopener">${H(l.name)} ↗</a><p>${H(l.focus)}</p></div><span class="tag">${H(l.org)}</span></div>`).join('')}</div>
<div class="section-title"><h2>Acervo importado por banca</h2></div><div class="card">${Object.keys(byBoard).length?Object.entries(byBoard).sort((a,b)=>b[1]-a[1]).map(([x,n])=>`<div class="row between target-row"><strong>${H(x)}</strong><span>${n} questões</span></div>`).join(''):'<p class="listnote">Ainda não há provas históricas importadas. A versão inicial mantém 166 questões autorais comentadas para treino imediato.</p>'}</div>
<div class="section-title"><h2>Backup e recuperação</h2></div><div class="card"><p class="listnote">Exporte histórico, notas e banco de questões completo como JSON. O backup pode ser importado em outro iPhone ou computador; não existe sincronização em nuvem.</p><div class="buttons"><button class="btn small" data-action="backup">Exportar tudo</button><button class="btn small" data-action="restore">Restaurar backup</button></div><input class="hide" type="file" id="backup-file" accept="application/json,.json"></div>`}
function pickRandom(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function start(mode,config={}){let source=all().filter(q=>q.options?.length>=2),past=new Set(base.history.map(h=>h.id));let pool=source.filter(q=>(!config.subject||config.subject==='all'||q.subject===config.subject)&&(!config.topic||config.topic==='all'||q.topicId===config.topic)&&(!config.kind||config.kind==='all'||q.kind===config.kind));if(mode==='errors'){const wrong=new Set(base.history.filter(h=>!h.correct).map(h=>h.id));pool=pool.filter(q=>wrong.has(q.id));}
let chosen=[];
if(mode==='mock'){pool=pool.filter(q=>q.options.length===5);const requirements=SUBJECTS.map(s=>({id:s.id,n:s.examCount}));for(const r of requirements){const items=pickRandom(pool.filter(q=>q.subject===r.id));if(items.length<r.n){alert(`Banco insuficiente para simulado: ${nameSubject(r.id)} exige ${r.n} questões, mas há ${items.length} neste filtro. Escolha Todas as origens ou importe mais questões.`);return}chosen.push(...items.slice(0,r.n))}chosen=pickRandom(chosen)}
else{const fresh=pickRandom(pool.filter(q=>!past.has(q.id))),old=pickRandom(pool.filter(q=>past.has(q.id)));chosen=[...fresh,...old].slice(0,config.count||15)}
if(!chosen.length){alert('Não há questões disponíveis com esse filtro. Importe provas anteriores ou selecione as questões autorais.');return}
session={mode,questions:chosen,answers:{},at:0,start:Date.now(),reasoned:{}};page='session';render();window.scrollTo(0,0)}
function questionPage(){if(!session)return home();const q=session.questions[session.at],ans=session.answers[q.id],answered=ans!==undefined,isMock=session.mode==='mock';const reviewed=answered&&!isMock;let reason=base.errorReasons[q.id]||'';return `<div class="quiz-frame"><div class="quiz-top"><span class="tag">${H(nameSubject(q.subject))}</span><span class="tiny">${session.at+1}/${session.questions.length}</span></div><div class="progressbar"><span style="width:${percent(session.at+1,session.questions.length)}%"></span></div><div class="tiny">${dLabel(q)}</div><h2 class="question">${H(q.prompt)}</h2>${!q.options?.length?`<div class="card"><p>Registro de questão externa: <a href="${safeUrl(q.sourceUrl)}" target="_blank" rel="noopener">abrir caderno original ↗</a>. Use o PDF para conferir o enunciado e a resolução.</p></div>`:`<div class="options">${q.options.map((x,i)=>`<button class="option ${reviewed?(i===q.answer?'correct':i===ans?'wrong':''):answered&&i===ans?'chosen':''}" data-action="answer" data-index="${i}" ${reviewed?'disabled':''}><span class="letter">${letters(q)[i]}</span>${H(x)}</button>`).join('')}</div>`}
${reviewed?`<div class="feedback ${ans!==q.answer?'error':''}"><strong>${ans===q.answer?'✓ Correto':'✗ Resposta incorreta'} · ${letters(q)[q.answer]}</strong><p>${q.explanation?H(q.explanation):'Não há explicação cadastrada para esta questão. Consulte o caderno oficial e registre o raciocínio na sua anotação.'}</p><p class="tiny">Assunto associado: ${H(Tp(q.topicId)?.name||q.topic)}</p>${q.sourceUrl?`<a href="${safeUrl(q.sourceUrl)}" target="_blank" rel="noopener">Conferir prova de origem ↗</a>`:''}</div>${ans!==q.answer?`<div class="card" style="margin-top:10px"><strong>Por que errei?</strong><div class="reasons">${['Conceito','Interpretação','Cálculo','Desatenção'].map(r=>`<button class="reason ${reason===r?'selected':''}" data-action="reason" data-reason="${r}" data-id="${H(q.id)}">${r}</button>`).join('')}</div><p class="tip">💡 ${H(Tp(q.topicId)?.tip||'Revise a premissa e diferencie as alternativas.')}</p></div>`:''}`:''}
${isMock?`<div class="question-grid">${session.questions.map((x,i)=>`<button class="qdot ${session.answers[x.id]!==undefined?'done':''} ${i===session.at?'active':''}" data-action="jump" data-index="${i}">${i+1}</button>`).join('')}</div>`:''}
<div class="quiz-actions"><button class="btn small" data-action="prev" ${session.at===0?'disabled':''}>← Anterior</button>${session.at===session.questions.length-1?`<button class="btn primary" data-action="finish">Corrigir rodada →</button>`:`<button class="btn primary" data-action="next" ${!isMock&&!answered?'disabled':''}>Próxima →</button>`}</div><button class="btn small danger" style="margin-top:15px" data-action="quit">Sair do treino</button></div>`}
function record(q,ans){base.history.push({id:q.id,subject:q.subject,topicId:q.topicId,date:new Date().toISOString(),correct:ans===q.answer,selected:ans,kind:q.kind});save()}
function finish(){if(!session)return;if(session.mode==='mock'){for(const q of session.questions){if(session.answers[q.id]!==undefined)record(q,session.answers[q.id]);}const cs=scoreSession();base.sessions.push({date:new Date().toISOString(),points:cs.points,correct:cs.correct,total:session.questions.length,kind:'simulado'});save()}page='result';render();window.scrollTo(0,0)}
function scoreSession(){let points=0,correct=0;const per={};for(const q of session.questions){const a=session.answers[q.id];const x=per[q.subject]??={correct:0,total:0};x.total++;if(a===q.answer){correct++;x.correct++;points+=S(q.subject).weight;}}return {points,correct,per}}
function result(){if(!session)return home();const x=scoreSession(),n=session.questions.length;return `<div class="page-header"><div class="eyebrow">Rodada concluída</div><h1>Seu desempenho</h1><p>Erros, acertos e comentários ficam registrados para os diagnósticos futuros.</p></div><div class="grid two"><div class="card center"><div class="stat-label">Acertos</div><div class="result-score">${x.correct}<span class="muted" style="font-size:22px">/${n}</span></div><p class="listnote">${percent(x.correct,n)}% de acertos</p></div><div class="card center"><div class="stat-label">Pontos ponderados</div><div class="result-score">${x.points.toFixed(2).replace('.',',')}</div><p class="listnote">${session.mode==='mock'?'de 25,00 pontos':'Nesta rodada'}</p></div></div><div class="card" style="margin-top:14px">${SUBJECTS.filter(s=>x.per[s.id]).map(s=>`<div class="row between target-row"><span>${H(s.name)}</span><strong>${x.per[s.id].correct}/${x.per[s.id].total}</strong></div>`).join('')}</div><div class="section-title"><h2>Correção comentada</h2></div>${session.questions.map((q,i)=>{const ans=session.answers[q.id],ok=ans===q.answer;return `<details class="review-item"><summary>${ok?'✅':'❌'} ${i+1}. ${H(q.prompt.slice(0,135))}</summary><p>Origem: ${dLabel(q)}. <strong>Gabarito: ${letters(q)[q.answer]}</strong> · Sua resposta: ${ans===undefined?'em branco':letters(q)[ans]}.</p><p>${H(q.explanation||'Comentário não cadastrado; confira a prova oficial e registre sua explicação.')}</p><p class="tip">${H(Tp(q.topicId)?.tip||'')}</p>${q.sourceUrl?`<a target="_blank" rel="noopener" href="${safeUrl(q.sourceUrl)}">Prova original ↗</a>`:''}</details>`}).join('')}<div class="buttons"><button class="btn primary" data-page="gaps">Revisar lacunas</button><button class="btn" data-page="practice">Novo treino</button></div>`}
function render(){const body=page==='home'?home():page==='plan'?plan():page==='gaps'?gaps():page==='bank'?bank():page==='practice'?practice():page==='session'?questionPage():page==='result'?result():home();layout(body)}
function goto(p){if(page==='session'&&session&&!['session','result'].includes(p)){if(!confirm('Sair da rodada? As respostas já registradas serão mantidas, mas a sessão atual será encerrada.'))return;session=null}page=p;render();window.scrollTo(0,0)}
function parseCSV(s){s=s.replace(/^\ufeff/,'');const first=s.split(/\r?\n/,1)[0],sep=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':',';let rows=[],r=[],v='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i],next=s[i+1];if(c==='"'){if(quoted&&next==='"'){v+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){r.push(v);v=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&next==='\n')i++;r.push(v);if(r.some(y=>y.trim()))rows.push(r);r=[];v=''}else v+=c}r.push(v);if(r.some(y=>y.trim()))rows.push(r);if(rows.length<2)return[];const head=rows[0].map(x=>x.trim().toLowerCase());return rows.slice(1).map(line=>Object.fromEntries(head.map((h,i)=>[h,(line[i]||'').trim()])))}
const field=(obj,...keys)=>{for(const k of keys){if(obj[k]!==undefined&&obj[k]!==null&&String(obj[k]).trim()!=='')return obj[k]}return''};
function normalizeImported(raw){const id=String(field(raw,'id','codigo','identificador')).trim(),sub=String(field(raw,'materia','subject','disciplina')).trim(),topicId=String(field(raw,'topico_id','topicid','topic_id')).trim();const board=String(field(raw,'banca','board')).trim(),year=Number(field(raw,'ano','year')),exam=String(field(raw,'prova','exam')).trim(),questionNo=Number(field(raw,'numero','numero_questao','questionno')),sourceUrl=String(field(raw,'url_fonte','sourceurl','fonte_url')).trim();const prompt=String(field(raw,'enunciado','prompt','questao')).trim(),expl=String(field(raw,'comentario','explicacao','explanation')).trim();let opts=['a','b','c','d','e'].map(l=>String(field(raw,'alternativa_'+l,'opcao_'+l,l)).trim());const key=String(field(raw,'gabarito','answer','resposta')).trim().toUpperCase(),isCE=String(field(raw,'tipo','type')).trim().toUpperCase()==='CE';if(isCE){opts=[opts[0]||'Certo',opts[1]||'Errado'];}const ans=isCE?(key==='C'||key==='CERTO'?0:key==='E'||key==='ERRADO'?1:-1):/^[ABCDE]$/.test(key)?'ABCDE'.indexOf(key):/^[0-4]$/.test(key)?Number(key):-1;const topic=Tp(topicId);
if(!S(sub)||!topic||topic.subject!==sub||ans<0||opts.some(x=>!x)||!prompt)throw Error(`Questão ${id||'(sem id)'}: matéria, tópico, enunciado, alternativas e gabarito são obrigatórios (A–E ou C/E).`);
const applied=board&&Number.isInteger(year)&&year>=1990&&year<=2026&&exam&&Number.isInteger(questionNo)&&questionNo>0&&/^https?:\/\//.test(sourceUrl);
const uid=(applied?'ref:':'imp:')+ (applied?[board,year,exam,questionNo]:['avulsa',id||prompt.slice(0,90)]).join(':').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,'_');
return {id:uid,subject:sub,topicId,topic:topic.name,prompt,options:opts,answer:ans,explanation:expl,kind:applied?'aplicada':'autoral',board:board||'Sem banca',year:year||'',exam:exam||'Não informado',questionNo:questionNo||'',sourceUrl:applied?sourceUrl:'',origin:'Dados declarados pelo importador'} }
function download(name,text,contentType='application/json'){const blob=new Blob([text],{type:contentType}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function importQuestions(files){let parsed=[],bad=[];for(const f of files){try{const s=await f.text(),obj=f.name.toLowerCase().endsWith('.csv')?parseCSV(s):JSON.parse(s),rows=Array.isArray(obj)?obj:Array.isArray(obj.questions)?obj.questions:null;if(!rows)throw Error('Esperado array de questões');for(let i=0;i<rows.length;i++){try{parsed.push(normalizeImported(rows[i]))}catch(e){if(bad.length<8)bad.push(`linha ${i+2}: ${e.message}`)}}}catch(e){bad.push(`${f.name}: ${e.message}`)}}
const seed=new Set(D.questions.map(q=>q.id));parsed=[...new Map(parsed.filter(q=>!seed.has(q.id)).map(q=>[q.id,q])).values()];let already=new Set(imported.map(x=>x.id)),news=parsed.filter(q=>!already.has(q.id));if(parsed.length){try{await addDb(parsed);imported=await loadDb();reindex()}catch(e){alert('Erro ao salvar banco importado: '+e.message);return}}
alert(`${news.length} novas questões adicionadas; ${parsed.length-news.length} atualizadas. ${bad.length} problema(s) de formato.${bad.length?'\n'+bad.join('\n'):''}\n\nQuestões declaradas como históricas exigem banca, ano, prova, número e URL de origem; autenticidade não é verificada automaticamente.`);render()}
async function manualRegister(){const board=$('#m-board')?.value.trim(),year=Number($('#m-year')?.value),exam=$('#m-exam')?.value.trim(),number=Number($('#m-number')?.value),subject=$('#m-sub')?.value,topicId=$('#m-topic')?.value,url=$('#m-url')?.value.trim(),ok=$('#m-result')?.value==='ok',comment=$('#m-comment')?.value.trim();if(!board||!exam||!Number.isInteger(year)||year<1990||year>2026||!Number.isInteger(number)||number<=0||!subject||!topicId||!/^https?:\/\//.test(url)){alert('Preencha banca, ano, prova, número, matéria, tópico e URL pública válida da prova.');return}
const id='ref:'+ [board,year,exam,number].join(':').toLowerCase().normalize('NFKC').replace(/\s+/g,'_');const q={id,subject,topicId,topic:Tp(topicId).name,prompt:`Questão ${number} — ${board} ${year}, ${exam}. Consulte o caderno original.`,options:[],answer:0,explanation:comment,kind:'aplicada',board,year,exam,questionNo:number,sourceUrl:url,origin:'Registro manual do usuário'};
try{await addDb([q]);imported=await loadDb();reindex()}catch(e){alert('Não foi possível guardar a referência no dispositivo: '+e.message);return}base.history.push({id,subject,topicId,date:new Date().toISOString(),correct:ok,selected:ok?0:1,kind:'aplicada'});save();alert('Questão registrada. Você poderá localizá-la no histórico e no diagnóstico. O texto da prova continua na fonte original.');render()}
async function importResults(files){let entries=[],bad=[];for(const f of files){try{const data=parseCSV(await f.text());if(!data.length)throw Error('CSV vazio. Use o modelo do aplicativo.');for(const [i,r] of data.entries()){try{const board=String(field(r,'banca')).trim(),year=Number(field(r,'ano')),exam=String(field(r,'prova')).trim(),questionNo=Number(field(r,'numero')),subject=String(field(r,'materia')),topicId=String(field(r,'topico_id')),res=String(field(r,'resultado')).trim().toLowerCase(),url=String(field(r,'url_fonte')).trim(),comment=String(field(r,'comentario')).trim();if(!board||year<1990||year>2026||!Number.isInteger(year)||!exam||!Number.isInteger(questionNo)||questionNo<1||!S(subject)||!Tp(topicId)||Tp(topicId).subject!==subject||!['acertei','errei','certo','errado','ok','erro','1','0'].includes(res)||!/^https?:\/\//.test(url))throw Error('Origem, tópico, resultado ou URL inválidos');const ok=['acertei','certo','ok','1'].includes(res),id='ref:'+ [board,year,exam,questionNo].join(':').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,'_');entries.push({q:{id,subject,topicId,topic:Tp(topicId).name,prompt:`Questão ${questionNo} — ${board} ${year}, ${exam}. Consulte o caderno original.`,options:[],answer:0,explanation:comment,kind:'aplicada',board,year,exam,questionNo,sourceUrl:url,origin:'Resultado declarado pelo usuário'},ok})}catch(e){if(bad.length<8)bad.push(`${f.name} linha ${i+2}: ${e.message}`)}}}catch(e){bad.push(`${f.name}: ${e.message}`)}}if(!entries.length){alert('Nenhum registro válido. '+bad.join('\n'));return}try{await addDb(entries.map(x=>x.q));imported=await loadDb();reindex()}catch(e){alert('Falha no banco local: '+e.message);return}for(const x of entries){base.history.push({id:x.q.id,subject:x.q.subject,topicId:x.q.topicId,date:new Date().toISOString(),correct:x.ok,selected:x.ok?0:1,kind:'aplicada'})}save();alert(`${entries.length} resultados registrados. Repetições de um mesmo caderno e número só contam 1 vez na meta. ${bad.length?'Avisos:\n'+bad.join('\n'):''}`);render()}
async function restoreBackup(f){try{const obj=JSON.parse(await f.text()),p=obj.progress||obj.data,qs=obj.questions;if(!p||!Array.isArray(p.history)||!Array.isArray(qs))throw Error('Arquivo incompatível');if(!confirm(`Este backup contém ${p.history.length} tentativas e ${qs.length} questões. Substituir dados locais?`))return;await clearDb();await addDb(qs);base={history:p.history||[],sessions:p.sessions||[],lessons:p.lessons||[],notes:p.notes||{},errorReasons:p.errorReasons||{}};imported=await loadDb();reindex();save();alert('Backup restaurado.');render()}catch(e){alert('Não foi possível restaurar: '+e.message)}}
async function clickAction(el){const a=el.dataset.action;if(a==='start-filter'){start('practice',{...practiceFilter});}
if(a==='start-mock'){start('mock',{kind:practiceFilter.kind});}
if(a==='start-errors'){start('errors',{kind:'all',count:20});}
if(a==='train-topic'){const t=Tp(el.dataset.topic);if(!t)return;start('practice',{subject:t.subject,topic:t.id,kind:'all',count:15});}
if(a==='answer'){if(!session)return;const q=session.questions[session.at],chosen=Number(el.dataset.index);if(session.mode==='mock'){session.answers[q.id]=chosen;render();return}if(session.answers[q.id]!==undefined)return;session.answers[q.id]=chosen;record(q,chosen);render()}
if(a==='reason'){base.errorReasons[el.dataset.id]=el.dataset.reason;save();render()}
if(a==='next'){if(session.at<session.questions.length-1){session.at++;render();window.scrollTo(0,0)}}
if(a==='prev'){if(session.at>0){session.at--;render();window.scrollTo(0,0)}}
if(a==='jump'){session.at=Number(el.dataset.index);render()}
if(a==='finish'){if(session.mode==='mock'&&Object.keys(session.answers).length<60&&!confirm('Existem questões em branco, que não serão pontuadas. Corrigir assim mesmo?'))return;finish()}
if(a==='quit'){if(confirm('Sair? O progresso já registrado será preservado.')){session=null;page='home';render()}}
if(a==='note-topic'){noteTopic=el.dataset.topic;render();setTimeout(()=>$('#topic-note')?.focus(),20)}
if(a==='save-topic-note'){base.notes[el.dataset.topic]=$('#topic-note')?.value||'';save();noteTopic=null;render()}
if(a==='import-questions')$('#questions-file')?.click();
if(a==='download-model'){const h='id,banca,ano,prova,numero,materia,topico_id,enunciado,alternativa_a,alternativa_b,alternativa_c,alternativa_d,alternativa_e,gabarito,comentario,url_fonte';download('modelo_questoes_ABDI.csv',h+'\n','text/csv;charset=utf-8')}
if(a==='download-results-model'){download('modelo_resultados_ABDI.csv','banca,ano,prova,numero,materia,topico_id,resultado,url_fonte,comentario\n','text/csv;charset=utf-8')}
if(a==='import-results')$('#results-file')?.click();
if(a==='download-topics'){const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const rows=['topico_id,materia,assunto',...T.map(t=>[t.id,t.subject,t.name].map(esc).join(','))];download('mapa_topicos_ABDI_2026.csv','\ufeff'+rows.join('\n')+'\n','text/csv;charset=utf-8')}
if(a==='manual-register')await manualRegister();
if(a==='backup')download('backup_Rumo_ABDI_3000.json',JSON.stringify({version:2,createdAt:new Date().toISOString(),progress:base,questions:imported},null,2));
if(a==='restore')$('#backup-file')?.click()}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-page],[data-action]');if(!el)return;if(el.dataset.page)goto(el.dataset.page);else await clickAction(el)});
document.addEventListener('change',async e=>{const el=e.target;
if(el.id==='p-sub'){practiceFilter.subject=el.value;practiceFilter.topic='all';render()}
if(el.id==='p-topic'){practiceFilter.topic=el.value;render()}
if(el.id==='p-kind'){practiceFilter.kind=el.value;render()}
if(el.id==='p-count'){practiceFilter.count=Number(el.value);render()}
if(el.id==='gap-status'){gapFilter=el.value;noteTopic=null;render()}
if(el.id==='m-sub'){const options=T.filter(t=>t.subject===el.value).map(t=>`<option value="${t.id}">${H(t.name)}</option>`).join('');$('#m-topic').innerHTML=`<option value="">Escolher tópico</option>${options}`}
if(el.id==='questions-file'){if(el.files.length)await importQuestions([...el.files])}
if(el.id==='results-file'){if(el.files.length)await importResults([...el.files])}
if(el.id==='backup-file'&&el.files[0])await restoreBackup(el.files[0]);});
async function init(){await openDb();imported=await loadDb();reindex();render();if('serviceWorker'in navigator&&/^https?:/.test(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{})}init();
})();
